mapper.select:
SELECT COUNT(*)
FROM salary_slip
WHERE employee_id = #{employeeId}
  AND pay_month = #{payMonth}

mapper.update:
UPDATE salary_slip
SET file_path = #{filePath},
    uploaded_by = #{uploadedBy},
    uploaded_at = now()
WHERE employee_id = #{employeeId}
AND pay_month = #{payMonth}

mapper.select:
